// src/Components/HomePage/Slider/Slider.jsx
import React, { useState, useEffect } from 'react';
import styles from './Slider.module.css';
import img1 from '../../assets/1.jpg';
import img2 from '../../assets/2.webp';
import img3 from '../../assets/3.jpg';

const slides = [
  { src: img1, caption: 'Save Big on Winter Deals!' },
  { src: img2, caption: 'Up to 50% Off Electronics' },
  { src: img3, caption: 'Exclusive Cash Back Offers' },
];

export const Slider = () => {
  const [currentIndex, setCurrentIndex] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentIndex((prev) => (prev === slides.length - 1 ? 0 : prev + 1));
    }, 5000); // Auto-play every 5 seconds
    return () => clearInterval(interval);
  }, []);

  const prevSlide = () => setCurrentIndex((prev) => (prev === 0 ? slides.length - 1 : prev - 1));
  const nextSlide = () => setCurrentIndex((prev) => (prev === slides.length - 1 ? 0 : prev + 1));

  return (
    <div className={styles.slider}>
      <button className={styles.leftButton} onClick={prevSlide}>❮</button>
      <div className={styles.slide}>
        <img src={slides[currentIndex].src} alt="slider" className={styles.image} />
        <div className={styles.caption}>{slides[currentIndex].caption}</div>
      </div>
      <button className={styles.rightButton} onClick={nextSlide}>❯</button>
    </div>
  );
};
